<script>
export default {
  name: 'UserForm',
  props: {
    visible: Boolean,
    userData: Object
  },
  data() {
    return {
      form: { name: '', email: '' },
      rules: {
        name: [{ required: true, message: '请输入姓名', trigger: 'blur' }],
        email: [{ required: true, message: '请输入邮箱', trigger: 'blur' }]
      }
    };
  },
  computed: {
    isEdit() {
      return !!this.userData;
    }
  },
  watch: {
    userData(val) {
      if (val) this.form = { ...val };n    }
  },
  methods: {
    submit() {
      this.$refs.form.validate(valid => {
        if (valid) this.$emit('submit', this.form);
      });
    }
  }
};
</script>
